  ('Q_20261115_09_12', 'PG', 'Prakarya 9', 'Ciri tekstil non-tenun adalah ....', 'none', '', '["dibuat dengan menganyam benang secara horizontal dan vertical hingga menjadi lembaran", "dibuat dengan menyulam benang pada kain berpola hingga menjadi kerajinan tekstil yang menarik", "dibuat dari kain yang diikat lalu dicelup warna", "Dibuat dengan menyatukan serat melalui proses mekanis, kimiawi, atau termal tanpa proses tenun"]'::jsonb, '[]'::jsonb, 'Dibuat dengan menyatukan serat melalui proses mekanis, kimiawi, atau termal tanpa proses tenun', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_13', 'PG', 'Prakarya 9', 'Perhatikan langkah berikut!<br>1)	Menyiapkan alat dan bahan<br>2)	Membuat desain<br>3)	Finishing dan pengemasan<br>4)	Membuat produk<br>Urutan yang tepat dalam pembuatan kerajinan adalah ....', 'none', '', '["1-2-3-4", "2-4-1-3", "2-1-4-3", "1-4-2-3"]'::jsonb, '[]'::jsonb, '2-1-4-3', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_14', 'PG', 'Prakarya 9', 'Sebuah rumah produksi menerima pesanan ribuan meter kain dalam waktu singkat. Energi yang paling sesuai untuk mempercepat produksi dan meringankan pekerjaan adalah ....', 'none', '', '["ATBM yang digerakkan tenaga manusia", "alat pintal tangan sederhana", "tenaga mesin modern", "tenaga satu orang penenun"]'::jsonb, '[]'::jsonb, 'tenaga mesin modern', 10, 'Sesuai kunci jawaban.'),
