  ('Q_20261115_09_18', 'PG', 'Prakarya 9', 'Ibu memakai taplak meja dan sarung bantal dari kain untuk mendukung aktivitas seluruh anggota keluarga di rumah. Produk kerajinan tekstil tersebut memenuhi kebutuhan ....', 'none', '', '["keluarga", "individu", "masyarakat", "pasar global"]'::jsonb, '[]'::jsonb, 'keluarga', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_19', 'PG', 'Prakarya 9', 'Warga sebuah desa memakai kain tenun khas daerahnya pada upacara adat dan perayaan hari tertentu secara bersama-sama. Fungsi kain tersebut adalah memenuhi kebutuhan ....', 'none', '', '["individu", "keluarga", "industri pakaian", "masyarakat"]'::jsonb, '[]'::jsonb, 'masyarakat', 10, 'Sesuai kunci jawaban.'),
