  ('Q_20261115_09_38', 'PG', 'Prakarya 9', 'Batik yang proses pembentukan motifnya menggunakan cap dari tembaga disebut ....', 'none', '', '["batik tulis", "batik cap", "batik jumputan", "batik lukis"]'::jsonb, '[]'::jsonb, 'batik cap', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_39', 'PG', 'Prakarya 9', 'Salah satu produk yang dapat dibuat dengan teknik rajut adalah ....', 'none', '', '["tas", "batik tulis", "kain cap", "kain ecoprint"]'::jsonb, '[]'::jsonb, 'tas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_40', 'PG', 'Prakarya 9', 'Agar produk tidak hanya bernilai estetika tetapi juga memuat nilai budaya, motif yang dirancang sebaiknya ....', 'none', '', '["menggali kearifan lokal dan budaya di sekitar tempat tinggal", "meniru seluruh motif daerah lain tanpa perubahan agar terlihat bagus", "dibuat acak tanpa makna", "memakai motif asing yang sedang populer saja"]'::jsonb, '[]'::jsonb, 'menggali kearifan lokal dan budaya di sekitar tempat tinggal', 10, 'Sesuai kunci jawaban.')
INSERT INTO public.cbt_questions (id, type, subject, text, media_type, media_url, options, pairs, answer, weight, explanation) VALUES
  ('Q_20261115_09_41', 'PG', 'Prakarya 9', 'Dika membuat sketsa tas makrame. Setelah dicoba, tali bahunya sempit dan keras sehingga melukai bahu, sedangkan biaya bahan melebihi harga jual yang wajar. Revisi desain yang paling tepat adalah ....', 'none', '', '["mempertahankan desain dan menambah hiasan agar terlihat mahal", "memperlebar dan memperlembut tali bahu agar nyaman, serta memilih bahan yang lebih terjangkau agar modal sebanding dengan harga jual", "mengecilkan tali bahu agar bahan lebih hemat", "mengganti tali dengan bahan yang lebih keras agar kuat"]'::jsonb, '[]'::jsonb, 'memperlebar dan memperlembut tali bahu agar nyaman, serta memilih bahan yang lebih terjangkau agar modal sebanding dengan harga jual', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_42', 'PG', 'Prakarya 9', 'Perbedaan utama antara teknik batik dan sibori terletak pada ....', 'none', '', '["cara membentuk motif pada kain", "jenis kain yang digunakan", "ukuran kain", "fungsi kain"]'::jsonb, '[]'::jsonb, 'cara membentuk motif pada kain', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_43', 'PG', 'Prakarya 9', 'Perhatikan gambar kerajinan logo sekolah dan nama berikut!<br>Keratinan logo sekolah dihasilkan dengan teknik menghias kain yang hampir sama<br>dengan sulam, namun menggunakan mesin jahit sebagai alat kreasinya. Teknik pembuatan kerajinan ini disebut…<br><img src="./assets/soal/soal-0047.jpg" style="max-width:100%; border-radius:8px; margin-top:6px;"><br><img src="./assets/soal/soal-0048.jpg" style="max-width:100%; border-radius:8px; margin-top:6px;">', 'image', './assets/soal/soal-0049.jpg', '["bordir", "rajut", "makrame", "tenun"]'::jsonb, '[]'::jsonb, 'bordir', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_44', 'PG', 'Prakarya 9', 'Kain strimin dipasang pada bingkai sulam saat menyulam hiasan dinding benang wol agar ....', 'none', '', '["kain menjadi tahan air", "warna benang berubah sendiri", "motif tercetak otomatis", "proses menyulam lebih mudah"]'::jsonb, '[]'::jsonb, 'proses menyulam lebih mudah', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_45', 'PG', 'Prakarya 9', 'Seorang pengrajin membuat tas dari kain katun kemudian menghias permukaannya dengan motif daun menggunakan teknik ecoprint. Nilai yang ditambahkan melalui kegiatan tersebut adalah ....', 'none', '', '["nilai kerusakan", "nilai limbah", "nilai estetika", "nilai pengurangan fungsi"]'::jsonb, '[]'::jsonb, 'nilai estetika', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_46', 'PG', 'Prakarya 9', 'Sebuah kelompok usaha memproduksi kain ecoprint. Mereka menemukan bahwa penggunaan daun dari jenis yang berbeda menghasilkan motif dan warna yang berbeda pula. Untuk meningkatkan konsistensi kualitas, langkah yang paling tepat adalah ....', 'none', '', '["menggunakan semua jenis daun secara acak pada setiap produksi", "menghilangkan tahap pengujian agar proses lebih cepat", "mencatat jenis daun, kondisi bahan, proses pemanasan, dan perlakuan penguncian warna", "mengganti bahan kain setiap kali produksi tanpa melakukan pencatatan"]'::jsonb, '[]'::jsonb, 'mencatat jenis daun, kondisi bahan, proses pemanasan, dan perlakuan penguncian warna', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_47', 'PG', 'Prakarya 9', 'Perhatikan gambar berikut!<br>Produk tersebut merupakan hasil kerajinan tekstil dengan teknik…', 'image', './assets/soal/soal-0050.jpg', '["makrame", "rajut", "renda", "sibori"]'::jsonb, '[]'::jsonb, 'makrame', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_48', 'PG', 'Prakarya 9', 'Pada pewarnaan kain dengan teknik shibori memakai pewarna remasol, waterglass (water glass/natrium silikat) digunakan untuk ....', 'none', '', '["mengunci warna agar melekat kuat pada serat kain", "menghilangkan malam (lilin) dari kain", "mengencerkan zat warna agar lebih muda", "mengikat kain agar motif terbentuk"]'::jsonb, '[]'::jsonb, 'mengunci warna agar melekat kuat pada serat kain', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_49', 'PG', 'Prakarya 9', 'Pada pembuatan taplak meja dari kain perca katun, setelah kain perca dicuci bersih dan digunting sesuai desain, langkah berikutnya adalah ....', 'none', '', '["membakar tepi kain perca", "merendam kain dalam larutan tawas selama seminggu kemudian dicuci dan dijemur", "menumbuk kain dengan batu gilingan", "menjahit tiap bagian kain hingga menjadi selembar kain, lalu menjahit seluruh tepinya"]'::jsonb, '[]'::jsonb, 'menjahit tiap bagian kain hingga menjadi selembar kain, lalu menjahit seluruh tepinya', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261115_09_50', 'PG', 'Prakarya 9', 'Aldi membuat syal batik warna alam. Setelah direndam di rebusan secang, kain ia peras kuat lalu dijemur di bawah terik matahari, dan ia melewatkan perendaman larutan tawas. Hasilnya, warna syal pucat dan mudah pudar. Analisis penyebab yang paling tepat adalah ....', 'none', '', '["kain diperas dan dijemur langsung di bawah matahari, serta warna tidak dikunci dengan larutan tawas", "canting yang dipakai terlalu kecil", "motif yang digambar terlalu rumit", "ukuran kain terlalu kecil"]'::jsonb, '[]'::jsonb, 'kain diperas dan dijemur langsung di bawah matahari, serta warna tidak dikunci dengan larutan tawas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_01', 'PG', 'Bahasa Indonesia SMP 9', 'Objek yang dideskripsikan dalam teks tersebut adalah ....', 'none', '', '["Gunung Bromo", "Danau Toba", "Pantai Losari", "Danau Tempe"]'::jsonb, '[]'::jsonb, 'Danau Toba', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_02', 'PG', 'Bahasa Indonesia SMP 9', 'Bagaimana warna air Danau Toba berdasarkan teks?', 'none', '', '["Hitam kecokelatan", "Merah keemasan", "Biru kehijauan", "Putih keabu-abuan"]'::jsonb, '[]'::jsonb, 'Biru kehijauan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_03', 'PG', 'Bahasa Indonesia SMP 9', 'Apa yang terdapat di tengah Danau Toba?', 'none', '', '["Pulau Samosir", "Gunung Merapi", "Hutan mangrove", "Air terjun"]'::jsonb, '[]'::jsonb, 'Pulau Samosir', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_04', 'PG', 'Bahasa Indonesia SMP 9', 'Suasana di sekitar Danau Toba pada pagi hari adalah ....', 'none', '', '["Panas dan berdebu", "Sejuk dan menenangkan", "Ramai dan bising", "Gelap dan menyeramkan"]'::jsonb, '[]'::jsonb, 'Sejuk dan menenangkan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_05', 'PG', 'Bahasa Indonesia SMP 9', 'Kalimat yang menunjukkan penggunaan indra penglihatan adalah ....<br>Teks 2 untuk soal nomor 6–10<br>Cara Membuat Teh Manis Hangat<br>Teh manis hangat merupakan minuman sederhana yang mudah dibuat di rumah. Untuk membuatnya, siapkan satu kantong teh, dua sendok gula, satu gelas air panas, dan sebuah sendok.<br>Langkah pertama, masukkan kantong teh ke dalam gelas. Kedua, tuangkan air panas ke dalam gelas tersebut. Setelah itu, diamkan selama beberapa menit hingga air berubah warna menjadi kecokelatan.<br>Selanjutnya, masukkan gula ke dalam gelas dan aduk hingga larut. Terakhir, angkat kantong teh dan teh manis hangat siap disajikan.', 'none', '', '["Udara di sekitar danau terasa sejuk.", "Kabut tipis menyelimuti permukaan air.", "Suara burung terdengar dari kejauhan.", "Aroma bunga tercium di sekitar danau."]'::jsonb, '[]'::jsonb, 'Kabut tipis menyelimuti permukaan air.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_06', 'PG', 'Bahasa Indonesia SMP 9', 'Tujuan teks tersebut adalah ....', 'none', '', '["Menggambarkan rasa teh", "Menjelaskan cara membuat teh manis hangat", "Menceritakan pengalaman minum teh", "Menjelaskan sejarah teh"]'::jsonb, '[]'::jsonb, 'Menjelaskan cara membuat teh manis hangat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_07', 'PG', 'Bahasa Indonesia SMP 9', 'Bahan yang diperlukan untuk membuat teh manis adalah ....', 'none', '', '["Kopi, susu, dan gula", "Teh, gula, dan air panas", "Cokelat, air dingin, dan garam", "Sirup, es batu, dan susu"]'::jsonb, '[]'::jsonb, 'Teh, gula, dan air panas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_08', 'PG', 'Bahasa Indonesia SMP 9', 'Apa yang dilakukan setelah memasukkan kantong teh ke dalam gelas?', 'none', '', '["Memasukkan es batu", "Menuangkan air panas", "Menambahkan garam", "Mengangkat kantong teh"]'::jsonb, '[]'::jsonb, 'Menuangkan air panas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_09', 'PG', 'Bahasa Indonesia SMP 9', 'Mengapa gula harus diaduk hingga larut?', 'none', '', '["Agar warna teh berubah menjadi putih", "Agar gula tercampur merata dengan teh", "Agar air menjadi dingin", "Agar teh tidak memiliki aroma"]'::jsonb, '[]'::jsonb, 'Agar gula tercampur merata dengan teh', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_10', 'PG', 'Bahasa Indonesia SMP 9', 'Kata penghubung yang menunjukkan urutan langkah dalam teks tersebut adalah ....<br>Teks 3 untuk soal nomor 11–15<br>Ruang Kelasku<br>Ruang kelasku terletak di lantai dua gedung sekolah. Ruangan tersebut cukup luas dan memiliki jendela besar di bagian samping. Dindingnya berwarna putih dengan hiasan hasil karya siswa.<br>Di bagian depan terdapat papan tulis berwarna putih dan meja guru. Sementara itu, meja dan kursi siswa tersusun rapi dalam beberapa baris. Di sudut ruangan terdapat lemari yang digunakan untuk menyimpan buku dan perlengkapan belajar.<br>Ruang kelas kami selalu dijaga kebersihannya. Setiap pagi, siswa melaksanakan piket agar suasana belajar tetap nyaman.', 'none', '', '["Tetapi", "Karena", "Selanjutnya", "Walaupun"]'::jsonb, '[]'::jsonb, 'Selanjutnya', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_11', 'PG', 'Bahasa Indonesia SMP 9', 'Di manakah letak ruang kelas berdasarkan teks?', 'none', '', '["Di lantai satu", "Di lantai dua", "Di lantai tiga", "Di belakang gedung sekolah"]'::jsonb, '[]'::jsonb, 'Di lantai dua', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_12', 'PG', 'Bahasa Indonesia SMP 9', 'Bagaimana warna dinding ruang kelas tersebut?', 'none', '', '["Biru", "Hijau", "Putih", "Kuning"]'::jsonb, '[]'::jsonb, 'Putih', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_13', 'PG', 'Bahasa Indonesia SMP 9', 'Apa fungsi lemari di sudut ruangan?', 'none', '', '["Menyimpan sepatu siswa", "Menyimpan buku dan perlengkapan belajar", "Menyimpan makanan", "Menyimpan alat olahraga"]'::jsonb, '[]'::jsonb, 'Menyimpan buku dan perlengkapan belajar', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_14', 'PG', 'Bahasa Indonesia SMP 9', 'Mengapa siswa melaksanakan piket setiap pagi?', 'none', '', '["Agar kelas terlihat lebih ramai", "Agar suasana belajar tetap nyaman", "Agar siswa tidak mengikuti pelajaran", "Agar meja dan kursi dapat dipindahkan"]'::jsonb, '[]'::jsonb, 'Agar suasana belajar tetap nyaman', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_15', 'PG', 'Bahasa Indonesia SMP 9', 'Kalimat yang menunjukkan gambaran kondisi ruang kelas adalah ....<br>Teks 4 untuk soal nomor 16–20<br>Cara Membuat Tempat Pensil dari Botol Bekas<br>Botol plastik bekas dapat dimanfaatkan menjadi tempat pensil yang menarik. Selain mengurangi sampah, kegiatan ini juga melatih kreativitas.<br>Alat dan bahan:<br>Botol plastik bekas<br>Gunting<br>Lem<br>Kertas warna<br>Pita hias<br>Langkah-langkah:<br>Bersihkan botol plastik bekas hingga tidak ada kotoran yang menempel.<br>Potong bagian atas botol menggunakan gunting dengan hati-hati.<br>Lapisi bagian luar botol menggunakan kertas warna.<br>Tempelkan pita hias agar tempat pensil terlihat lebih menarik.<br>Diamkan beberapa saat hingga lem mengering.<br>Tempat pensil dari botol bekas siap digunakan.', 'none', '', '["Setiap pagi siswa datang ke sekolah.", "Ruangan tersebut cukup luas dan memiliki jendela besar.", "Guru memberikan tugas kepada siswa.", "Siswa belajar Bahasa Indonesia."]'::jsonb, '[]'::jsonb, 'Ruangan tersebut cukup luas dan memiliki jendela besar.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_16', 'PG', 'Bahasa Indonesia SMP 9', 'Bahan utama yang digunakan dalam kegiatan tersebut adalah ....', 'none', '', '["Kardus bekas", "Botol plastik bekas", "Kaleng makanan", "Kain perca"]'::jsonb, '[]'::jsonb, 'Botol plastik bekas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_17', 'PG', 'Bahasa Indonesia SMP 9', 'Apa yang dilakukan sebelum memotong botol?', 'none', '', '["Membersihkan botol", "Menempelkan pita", "Mengeringkan lem", "Melapisi botol dengan kertas"]'::jsonb, '[]'::jsonb, 'Membersihkan botol', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_18', 'PG', 'Bahasa Indonesia SMP 9', 'Mengapa botol harus dipotong dengan hati-hati?', 'none', '', '["Agar botol berubah warna", "Agar tidak melukai tangan", "Agar lem cepat mengering", "Agar kertas mudah dilepas"]'::jsonb, '[]'::jsonb, 'Agar tidak melukai tangan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_19', 'PG', 'Bahasa Indonesia SMP 9', 'Apa manfaat kegiatan tersebut selain menghasilkan tempat pensil?', 'none', '', '["Menambah jumlah sampah", "Mengurangi sampah dan melatih kreativitas", "Menghabiskan bahan plastik baru", "Membuat lingkungan semakin kotor"]'::jsonb, '[]'::jsonb, 'Mengurangi sampah dan melatih kreativitas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_20', 'PG', 'Bahasa Indonesia SMP 9', 'Langkah terakhir sebelum tempat pensil digunakan adalah ....<br>Teks 5 untuk soal nomor 21–25<br>Perpustakaan Daerah<br>Perpustakaan daerah merupakan tempat yang menyediakan berbagai jenis bahan bacaan untuk masyarakat. Bangunannya cukup besar dengan desain yang sederhana. Bagian depan gedung dihiasi tanaman bunga yang tersusun rapi.<br>Ketika memasuki perpustakaan, pengunjung akan melihat rak-rak buku yang tersusun berdasarkan jenisnya. Ada buku cerita, ensiklopedia, buku sejarah, dan buku pengetahuan umum. Ruang bacanya dilengkapi meja dan kursi yang nyaman.<br>Suasana perpustakaan sangat tenang. Pengunjung dapat membaca buku, mengerjakan tugas, atau mencari informasi yang dibutuhkan.', 'none', '', '["Memotong botol", "Membersihkan botol", "Menunggu lem mengering", "Mengambil kertas warna"]'::jsonb, '[]'::jsonb, 'Menunggu lem mengering', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_21', 'PG', 'Bahasa Indonesia SMP 9', 'Apa yang disediakan oleh perpustakaan daerah?', 'none', '', '["Berbagai jenis bahan bacaan", "Berbagai jenis makanan", "Peralatan olahraga", "Pakaian dan sepatu"]'::jsonb, '[]'::jsonb, 'Berbagai jenis bahan bacaan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_22', 'PG', 'Bahasa Indonesia SMP 9', 'Bagaimana kondisi rak buku di perpustakaan?', 'none', '', '["Berantakan", "Kosong", "Tersusun berdasarkan jenisnya", "Diletakkan di luar gedung"]'::jsonb, '[]'::jsonb, 'Tersusun berdasarkan jenisnya', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_23', 'PG', 'Bahasa Indonesia SMP 9', 'Kegiatan yang dapat dilakukan pengunjung di perpustakaan adalah ....', 'none', '', '["Bermain sepak bola", "Membaca buku dan mengerjakan tugas", "Memasak makanan", "Menjual pakaian"]'::jsonb, '[]'::jsonb, 'Membaca buku dan mengerjakan tugas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_24', 'PG', 'Bahasa Indonesia SMP 9', 'Mengapa suasana perpustakaan dibuat tenang?', 'none', '', '["Agar pengunjung dapat membaca dengan nyaman", "Agar pengunjung tidak boleh berbicara selamanya", "Agar buku tidak terlihat", "Agar tidak ada orang yang datang"]'::jsonb, '[]'::jsonb, 'Agar pengunjung dapat membaca dengan nyaman', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_25', 'PG', 'Bahasa Indonesia SMP 9', 'Simpulan yang tepat berdasarkan teks adalah ....<br>Teks 6 untuk soal nomor 26–30<br>Cara Mencuci Tangan yang Benar<br>Mencuci tangan merupakan salah satu cara menjaga kebersihan dan kesehatan tubuh. Tangan yang kotor dapat menjadi tempat menempelnya kuman penyebab penyakit.<br>Berikut langkah-langkah mencuci tangan yang benar:<br>Basahi kedua tangan menggunakan air bersih.<br>Tuangkan sabun secukupnya ke telapak tangan.<br>Gosok kedua telapak tangan hingga berbusa.<br>Bersihkan sela-sela jari dan bagian punggung tangan.<br>Bilas tangan menggunakan air mengalir.<br>Keringkan tangan dengan tisu atau handuk bersih.<br>Dengan mencuci tangan secara benar, kita dapat mengurangi risiko penyebaran kuman dan penyakit.', 'none', '', '["Perpustakaan merupakan tempat untuk berjualan.", "Perpustakaan menyediakan bahan bacaan dan tempat yang nyaman untuk belajar.", "Perpustakaan hanya menyediakan buku cerita.", "Perpustakaan merupakan tempat bermain."]'::jsonb, '[]'::jsonb, 'Perpustakaan menyediakan bahan bacaan dan tempat yang nyaman untuk belajar.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_26', 'PG', 'Bahasa Indonesia SMP 9', 'Apa tujuan utama teks tersebut?', 'none', '', '["Menggambarkan bentuk tangan", "Menjelaskan cara mencuci tangan yang benar", "Menceritakan pengalaman mencuci tangan", "Menjelaskan sejarah sabun"]'::jsonb, '[]'::jsonb, 'Menjelaskan cara mencuci tangan yang benar', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_27', 'PG', 'Bahasa Indonesia SMP 9', 'Apa yang harus dilakukan setelah membasahi kedua tangan?', 'none', '', '["Mengeringkan tangan", "Menuangkan sabun", "Membilas tangan", "Menggunakan handuk"]'::jsonb, '[]'::jsonb, 'Menuangkan sabun', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_28', 'PG', 'Bahasa Indonesia SMP 9', 'Bagian tangan yang harus dibersihkan selain telapak tangan adalah ....', 'none', '', '["Rambut dan wajah", "Sela-sela jari dan punggung tangan", "Kaki dan lutut", "Bahu dan siku"]'::jsonb, '[]'::jsonb, 'Sela-sela jari dan punggung tangan', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_29', 'PG', 'Bahasa Indonesia SMP 9', 'Apa akibat jika seseorang tidak menjaga kebersihan tangannya?', 'none', '', '["Risiko penyebaran kuman dapat meningkat", "Tubuh menjadi lebih kuat", "Tangan selalu bersih", "Penyakit tidak akan menyerang"]'::jsonb, '[]'::jsonb, 'Risiko penyebaran kuman dapat meningkat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261117_09_30', 'PG', 'Bahasa Indonesia SMP 9', 'Mengapa langkah-langkah dalam teks prosedur harus disusun secara berurutan?', 'none', '', '["Agar teks terlihat lebih panjang", "Agar pembaca dapat mengikuti petunjuk dengan benar", "Agar pembaca merasa bingung", "Agar tidak perlu menggunakan alat"]'::jsonb, '[]'::jsonb, 'Agar pembaca dapat mengikuti petunjuk dengan benar', 10, 'Sesuai kunci jawaban.'),
